// 1D: iterate w DESCENDING so dp[w-wt] is still previous row
vector<int> dp(W + 1, 0);
for (auto [wt, val] : items)
  for (int w = W; w >= wt; w--)
    dp[w] = max(dp[w], val + dp[w - wt]);

// dp[i][j] = LCS of s1[0..i), s2[0..j)
